<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Edit User - DormSync</title><style>*{box-sizing:border-box}body{background:#f7f9fc;color:#172033;font-family:Arial,sans-serif;margin:0}.topbar{background:#fff;border-bottom:1px solid #e7ebf2;padding:18px 6%}.topbar a{color:#2563eb;text-decoration:none}main{margin:auto;max-width:620px;padding:38px 24px}.panel{background:#fff;border:1px solid #e7ebf2;border-radius:8px;padding:24px}h1{font-size:28px;margin:0 0 22px}label{display:block;font-size:13px;font-weight:600;margin:14px 0 6px}input,button{border:1px solid #cbd5e1;border-radius:6px;font:inherit;padding:11px;width:100%}button{background:#2563eb;border-color:#2563eb;color:#fff;cursor:pointer;font-weight:600;margin-top:18px}.error{color:#991b1b;font-size:13px}</style></head><body><header class="topbar"><a href="/admin/users">Back to users</a></header><main><section class="panel"><h1>Edit user</h1><?php foreach($errors as $fieldErrors):foreach((array)$fieldErrors as $error):?><p class="error"><?=htmlspecialchars($error)?></p><?php endforeach;endforeach;?><form method="post" action="/admin/user-edit/<?= (int)$user['id'] ?>"><label>Full name</label><input name="full_name" value="<?=htmlspecialchars($user['full_name'])?>" required><label>Email</label><input name="email" type="email" value="<?=htmlspecialchars($user['email'])?>" required><label>Phone</label><input name="phone" value="<?=htmlspecialchars($user['phone'] ?? '')?>"><?php if($warden): ?><label>Assigned block</label><input name="assigned_block" value="<?=htmlspecialchars($warden['assigned_block'] ?? '')?>" placeholder="A"><?php endif; ?><label>New password (optional)</label><input name="password" type="password"><button type="submit">Save user</button></form></section></main></body></html>
